def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def snapshot(account):
        return account, balances.get(account), account in frozen

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if (
            verb not in arities
            or len(parts) != arities[verb]
            or any(part == "" for part in parts)
        ):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for account, balance, was_frozen in history.pop():
                if balance is None:
                    balances.pop(account, None)
                else:
                    balances[account] = balance

                if was_frozen:
                    frozen.add(account)
                else:
                    frozen.discard(account)
            continue

        amount = 0
        if verb in ("open", "deposit", "withdraw", "transfer"):
            token = parts[-1]
            if not token.isascii() or not token.isdigit():
                rejected.append(index)
                continue

            # Small chunks avoid Python's limit on decimal string conversion.
            for start in range(0, len(token), 9):
                chunk = token[start:start + 9]
                amount = amount * (10 ** len(chunk)) + int(chunk)

            if verb != "open" and amount == 0:
                rejected.append(index)
                continue

        account = parts[1]

        if verb == "open":
            if account in balances:
                rejected.append(index)
                continue
            previous = [snapshot(account)]
            balances[account] = amount

        elif verb == "deposit":
            if account not in balances:
                rejected.append(index)
                continue
            previous = [snapshot(account)]
            balances[account] += amount

        elif verb == "withdraw":
            if (
                account not in balances
                or account in frozen
                or balances[account] < amount
            ):
                rejected.append(index)
                continue
            previous = [snapshot(account)]
            balances[account] -= amount

        elif verb == "transfer":
            destination = parts[2]
            if (
                account == destination
                or account not in balances
                or destination not in balances
                or account in frozen
                or balances[account] < amount
            ):
                rejected.append(index)
                continue
            previous = [snapshot(account), snapshot(destination)]
            balances[account] -= amount
            balances[destination] += amount

        elif verb == "freeze":
            if account not in balances or account in frozen:
                rejected.append(index)
                continue
            previous = [snapshot(account)]
            frozen.add(account)

        else:  # unfreeze
            if account not in balances or account not in frozen:
                rejected.append(index)
                continue
            previous = [snapshot(account)]
            frozen.remove(account)

        history.append(previous)

    return balances, rejected
